import {heatmapSVG,quantumCurveSVG as curve} from './quantum-plots.js?v=20261110-en1';
export const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const num=x=>Number.isFinite(x)?(x!==0&&(Math.abs(x)>=1e5||Math.abs(x)<1e-3)?x.toExponential(4):Number(x.toPrecision(5))):'—';
export const table=(heads,rows)=>`<div class="obs-table"><table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
export const notes=rows=>(rows||[]).length?`<aside class="mr-scope"><ul>${rows.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></aside>`:'';
export const sources=rows=>`<div class="obs-sources">${(rows||[]).filter(s=>/^https:\/\//.test(s.url||'')).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.title)} ↗</a>`).join('')}</div>`;
export const fields={
 hall:[['mass',"quality parameter m",-1,-5,5,.05],['energyScale',"Energy scale (eV)",1,.02,5,.02],['temperature',"temperature (K)",300,0,5000,10],['chemicalPotential',"chemical potential μ (eV)",0,-20,20,.01],['mesh',"Integration grid per direction N",61,15,121,1],['muMin',"μ scanning starting point (eV)",-3.5,-20,20,.1],['muMax',"μ Scan end point (eV)",3.5,-20,20,.1],['scanPoints',"scanning points",61,11,101,1]],
 device:[['model',"device model",'uniform',[['uniform',"uniform chain"],['ssh',"SSH alternate keychain"]]],['sites',"device grid points",12,2,40,1],['hopping',"benchmark transition (eV)",1,.05,5,.01],['dimerRatio',"SSH intracellular/intercellular transition ratio t₁/t₂",.6,.05,3,.05],['gate',"Uniform gate voltage energy (eV)",0,-10,10,.1],['barrier',"local barrier height (eV)",0,-10,10,.1],['barrierStart',"Barrier starting grid point (numbered from 0)",5,0,39,1],['barrierWidth',"Number of barrier grid points",1,1,40,1],['leadHopping',"electrode transition (eV)",1,.05,5,.01],['leadOnsite',"electrode on-site energy (eV)",0,-10,10,.1],['contactLeft',"left contact transition (eV)",1,0,5,.01],['contactRight',"right contact transition (eV)",1,0,5,.01],['energy',"Observation energy (eV)",.2,-20,20,.01],['energyMin',"Scan energy starting point (eV)",-2.5,-20,20,.1],['energyMax',"Scan energy end point (eV)",2.5,-20,20,.1],['samples',"scanning points",121,41,301,1],['eta',"Green function broadening eta (eV)",1e-7,1e-9,1e-3,'any'],['spinDegeneracy',"Number of independent spin channels",1,[[1,"1 · Spin-free model"],[2,"2 · Two identical independent spin channels"]]]],
 multiplet:[['electrons',"d Number of shell electrons N",6,0,10,1],['coordination',"ideal crystal field",'octahedral',[['octahedral',"Octahedron Oₕ"],['tetrahedral',"tetrahedron Tᵈ"]]],['splitting',"crystal field split Δ(eV)",1,0,10,.05],['coulombU',"co-orbital repulsion U (eV)",4,0,20,.1],['hundJ',"Hund coupling J (eV)",.6,0,2,.05],['scanMax',"ΔScan upper limit (eV)",5,.1,10,.1],['scanPoints',"Δ Scan points",21,3,41,1]]
};
export const defaultInputs=Object.fromEntries(Object.entries(fields).map(([id,list])=>[id,Object.fromEntries(list.map(f=>[f[0],f[2]]))]));
export const modelNotes={hall:"two-dimensional QWZ teaching model; σₓᵧ is the intrinsic sheet Hall conductance, αₓᵧ is the lateral thermoelectric coefficient. αₓᵧ is not directly equal to the open circuit Nernst voltage.",device:"Small-scale double-ended coherent, elastic, non-interacting transport . The observation energy is equal to the Fermi energy of the linear response at zero temperature; the bond flux is not the actual current at finite bias.",multiplet:"A five-orbital Kanamori model at fixed electron number, without SOC, including spin-flip and pair-hopping terms. It requires U ≥ 3J and does not model complete Slater multiplets or the spectrum of a real material."};
const select=(id,rows,value)=>`<select id="${id}">${rows.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select>`;
export function controlsHTML(module,input){return fields[module].map(([key,label,def,min,max,step])=>`<label>${esc(label)}${Array.isArray(min)?select('rp-'+key,min,input[key]??def):`<input id="rp-${key}" type="number" min="${min}" max="${max}" step="${step}" value="${esc(input[key]??def)}">`}</label>`).join('')+`<p class="obs-small">${esc(modelNotes[module])}</p>`;}
export function readControls(module,root,previous={}){const out={...previous};for(const [key,,def]of fields[module]){const value=root.querySelector('#rp-'+key).value;if(typeof def==='number'){if(!String(value).trim()||!Number.isFinite(Number(value)))throw Error("Numeric parameters must be limited numbers and cannot be left blank.");out[key]=Number(value);}else out[key]=value;}return out;}
function checksHTML(r){return `<details class="qm-checks"><summary>numerical verification and step-by-step derivation basis</summary>${table(["check item","results"],Object.entries(r.checks||{}).filter(([,v])=>['number','string','boolean'].includes(typeof v)).map(([k,v])=>[k,typeof v==='number'?num(v):typeof v==='boolean'?(v?"Yes":"No"):v]))}${(r.derivation||[]).map(s=>typeof s==='string'?`<p>${esc(s)}</p>`:`<h4>${esc(s.title)}</h4><div class="obs-formula">${esc(s.formula)}</div><p>${esc(s.text||s.explanation)}</p>`).join('')}</details>`;}
function hallSeries(r,key){return [true,false].map(resolved=>({label:resolved?"The comparison between the two grids has stabilized":"requires encryption verification",points:r.scan.rows.map((s,i)=>[r.scan.chemicalPotentials[i],s.defined&&s.numericallyResolved===resolved?s[key]:null])}));}
export function deviceDiagram(r){const n=r.device.sites.length,x=i=>85+510*i/Math.max(1,n-1);return `<svg class="rp-device" viewBox="0 0 700 200" role="img" aria-label="One-dimensional device with left and right electrodes connected"><title>node color indicates the positive and negative on-position energy; line width indicates the transition size</title><rect x="12" y="54" width="45" height="84" rx="8" fill="#d2e5dd"/><rect x="640" y="54" width="45" height="84" rx="8" fill="#d2e5dd"/><text x="12" y="35">left extreme</text><text x="637" y="35">right extreme</text><path d="M57 95H85M595 95H640" stroke="#658575" stroke-width="3" stroke-dasharray="5 4"/>${r.device.bonds.map(b=>`<line x1="${x(b.from)}" x2="${x(b.to)}" y1="95" y2="95" stroke="#427e6a" stroke-width="${Math.min(8,1+3*Math.abs(b.hopping))}"><title>t=${num(b.hopping)} eV</title></line>`).join('')}${r.device.sites.map(s=>`<circle cx="${x(s.index)}" cy="95" r="${n>24?5:8}" fill="${s.onsite>1e-9?'#b77f42':s.onsite< -1e-9?'#567aa5':'#27806a'}"><title>grid point ${s.index}; in position ${num(s.onsite)} eV</title></circle>${n<=16||s.index%5===0||s.index===n-1?`<text x="${x(s.index)}" y="130" text-anchor="middle">${s.index}</text>`:''}`).join('')}<text x="350" y="180" text-anchor="middle">Limited scattering zone · ${n} grid points</text></svg>`;}
export function resultHTML(module,r){let out='';if(module==='hall'){
 const s=r.selection;out=table(["physical quantity","results"],[['σₓᵧ（e²/h）',num(s.sigmaInE2OverH)],["σₓᵧ（S, chip response)",num(s.sigmaXY)],["αₓᵧ（A/K, chip response)",num(s.alphaXY)],["resolved direct energy gap (eV)",num(r.checks.analyticDirectGap)],["current points",s.defined?(s.numericallyResolved?"The comparison between the two grids has stabilized":"requires encryption verification"):"undefined"]])+notes([s.reason])+`<h3>Transverse response changes with chemical potential</h3>`+curve(hallSeries(r,'sigmaInE2OverH'),{xLabel:"chemical potential μ (eV)",yLabel:'σₓᵧ（e²/h）'})+curve(hallSeries(r,'alphaXY'),{xLabel:"chemical potential μ (eV)",yLabel:'αₓᵧ（A/K）'})+notes([`Scanning ${r.scan.rows.filter(s=>s.defined&&!s.numericallyResolved).length} points require encryption verification;${r.scan.rows.filter(s=>!s.defined).length} points are undefined. Green indicates that the comparison between the two grids has been stable, brown indicates the estimate to be verified; breakpoints are retained between the two categories.`])+`<details><summary>Point-by-point integration status and response</summary>${table(['μ（eV）','σₓᵧ（e²/h）','αₓᵧ（A/K）',"status"],r.scan.rows.map((s,i)=>[num(r.scan.chemicalPotentials[i]),num(s.sigmaInE2OverH),num(s.alphaXY),!s.defined?"undefined":s.numericallyResolved?"The comparison between the two grids has stabilized":"requires encryption verification"]))}</details><h3>From geometry to occupancy weighting</h3><label>heat map content${select('rp-field',[['berryCurvature',"lower band Berry curvature"],['occupiedCurvature',"Two-band occupation weighted curvature"],['entropyCurvature',"Two-band entropy weighted curvature"],['gap',"direct energy gap (eV)"]],'occupiedCurvature')}</label><div id="rp-map"></div><h3>Grid comparison of current μ and T</h3>`+table(["Grid N",'σₓᵧ（S）','αₓᵧ（A/K）',"lower band curvature integral"],r.convergence.map(c=>[c.mesh,num(c.sigmaXY),num(c.alphaXY),num(c.lowerBandChernIntegral)]));
 }else if(module==='device'){
 const s=r.selection;out=table(["physical quantity","results"],[["Observation energy (eV)",num(s.energy)],["transmittance T",num(s.transmission)],["reflectivity R",num(s.reflection)],["Conductivity （e²/h）",num(s.conductanceQuantum)],["Conductivity (S)",num(s.conductanceSiemens)],["broadened absorption",num(s.regulatorAbsorption)]])+deviceDiagram(r)+curve([{label:'T(E)',points:r.scan.energies.map((e,i)=>[e,r.scan.transmission[i]])}],{xLabel:"Energy E (eV)",yLabel:"transmittance T"})+`<h3>Local spectral weight at observed energy</h3>`+curve([{label:'LDOS',points:s.ldos.map((v,i)=>[i,v])},{label:"left electrode injection spectral density",points:s.leftInjectivity.map((v,i)=>[i,v])},{label:"right electrode injection spectral density",points:s.rightInjectivity.map((v,i)=>[i,v])}],{xLabel:"grid number",yLabel:"Spectral density per spin (1/eV)"})+`<h3>Left incident key flux</h3>`+curve([{label:"Normalized bond flux",points:s.bondTransmission.map((v,i)=>[i+.5,v])}],{xLabel:"key center (grid number)",yLabel:"Flux per left incident channel"})+notes(["Finite η introduces minor absorption; flux conservation should be checked compared to η. There are no propagation channels outside the electrode band and local spectral peaks may be present, but transmission cannot be reported based on this."])+`<details><summary>Extension and convergence details</summary><pre>${esc(JSON.stringify(r.checks.etaComparison,null,2))}</pre></details>`;
 }else{
 const g=r.ground;out=table(["physical quantity","results"],[["Fock space dimension with fixed N",r.dimension],["Electron number",r.parameters.electrons],["Ground state energy (eV)",num(g.energy)],["ground state degeneracy",g.degeneracy],["ground state ⟨S²⟩（ℏ²）",num(g.S2)],["ground state spin S",g.spins.join(', ')]])+`<h3>Select an energy and spin group</h3><label>multiple electron energy levels${select('rp-group',r.groups.map((g,i)=>[i,`${i} · ΔE=${num(g.relativeEnergy)} eV · S=${num(g.spin)} · ${g.degeneracy} heavy`]),0)}</label><div id="rp-occupations"></div><h3>crystal field Ground state change during enhancement</h3>`+curve([{label:'⟨S²⟩',points:r.scan.rows.map(s=>[s.splitting,s.S2])}],{xLabel:"crystal field split Δ(eV)",yLabel:"ground state ⟨S²⟩（ℏ²）"})+curve([{label:"ground state to excited state gap",points:r.scan.rows.map(s=>[s.splitting,s.gap])}],{xLabel:"crystal field split Δ(eV)",yLabel:"excitation gap (eV)"})+`<details><summary>Multi-electron energy level table (grouped by energy and S)</summary>${table(['ΔE（eV）',"degeneracy",'S','⟨S²⟩'],r.groups.map(g=>[num(g.relativeEnergy),g.degeneracy,num(g.spin),num(g.S2)]))}</details>`;
 }return out+notes(r.warnings)+checksHTML(r)+sources(r.sources);}
export function bindResult(module,r,root){if(module==='hall'){const field=root.querySelector('#rp-field'),target=root.querySelector('#rp-map');const update=()=>{const h=r.heatmap;target.innerHTML=heatmapSVG(h.kx,h.ky,h[field.value],{title:({berryCurvature:"lower band Berry curvature",occupiedCurvature:"occupies weighted curvature",entropyCurvature:"entropy weighted curvature",gap:"direct energy gap"})[field.value],signed:field.value!=='gap',xLabel:'kₓ（rad）',yLabel:'kᵧ（rad）'});};field.onchange=update;field.value='occupiedCurvature';update();}if(module==='multiplet'){const choice=root.querySelector('#rp-group'),target=root.querySelector('#rp-occupations');const update=()=>{const g=r.groups[Number(choice.value)];target.innerHTML=table(["track","Single electron energy (eV)","The average occupancy of this multi-electron group"],r.orbitalLabels.map((l,i)=>[l,num(r.orbitalEnergies[i]),num(g.orbitalOccupations[i])]))+`<p>Averaged within the same energy and spin subspace, the sum of the five occupations is ${r.parameters.electrons}; Single track occupancy range is 0–2.</p>`;};choice.onchange=update;update();}}
